package alcaldedigital.mision8;
import alcaldedigital.cliente.mision8.*;
import alcaldedigital.compartido.modelo.*;
import alcaldedigital.compartido.carrera.*;
import alcaldedigital.compartido.guardado.*;
import org.junit.jupiter.api.*;import java.util.*;import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

public class MisionOchoTest {
 public static AntecedentesOcho antecedentes(int candidato,boolean corrupto){var c=new EstadoCiudad(75,75,70,70,70,20,20);int[]apoyo={30,30,30,30};apoyo[candidato]=90;var e=new EstadoElectoral(corrupto,apoyo,new int[]{75,60,60,60},new int[]{10,10,10,10},new int[]{0,0,0,0},new int[]{10,10,10,10},List.of());return new AntecedentesOcho(c,e,Map.of("m1.publicaciones_responsables",3,"m4.respuestas_favorables",3,"m4.respuestas_desfavorables",0,"m5.publicaciones_verificadas",4),List.of("M4: No favorable","M6: Convicción válida"));}
 public static void cerrarConversacion(MotorOcho m){var escena=m.escena;int limite=30;while(m.escena==escena&&limite-->0){var l=HistoriaOcho.actual(m);if(l==null)throw new IllegalStateException("Sin diálogo");for(int t=0;t<Math.max(l.duracion(),(int)Math.ceil(l.texto().length()/.75))+1;t++)m.paso();m.avanzar();}assertNotEquals(escena,m.escena,"La conversación no terminó");}
 public static MotorOcho combate(int candidato,boolean corrupto,int n,int d,int rol){MotorOcho m=new MotorOcho(antecedentes(candidato,corrupto),n,d,rol,n==4,123);cerrarConversacion(m);cerrarConversacion(m);for(int i=0;i<3;i++)m.auditar(i,true);for(int i=0;i<n;i++)m.votar(i,candidato==0&&corrupto?1:candidato);cerrarConversacion(m);cerrarConversacion(m);assertEquals(MotorOcho.Escena.COMBATE,m.escena);return m;}
 @Test void lasCuatroCandidaturasConservanGanadorYAuditoria(){for(int c=0;c<4;c++){MotorOcho m=combate(c,false,1,1,0);assertEquals(c,m.ganador);assertEquals(0,m.avl.cantidad());assertEquals(7,m.difusion.size());assertTrue(m.decisiones.buscar("d0v").ejecutado());}}
 @Test void pactoNoSeCompensaConVotosOPuntaje(){MotorOcho m=combate(0,true,3,1,0);assertNotEquals(0,m.ganador);assertEquals(Integer.MIN_VALUE,m.respaldo(0));assertTrue(m.epilogo().contains("no lo vuelve elegible"));assertNotEquals("CONFIANZA CÍVICA",m.antecedentes.estadoCiudad());}
 @Test void unVotoNoPuedeElegirAlCandidatoSinRespaldo(){MotorOcho m=new MotorOcho(antecedentes(2,false),1,1,0,false,1);m.escena=MotorOcho.Escena.AUDITORIA;for(int i=0;i<3;i++)m.auditar(i,false);m.votar(0,0);assertEquals(2,m.ganador);assertEquals(3,m.publicado);}
 @Test void clasificacionTieneTresEstadosYNoPenalizaConviccion(){var a=antecedentes(0,false);assertEquals("CONFIANZA CÍVICA",a.estadoCiudad());assertEquals("CIUDAD EN CRISIS",new AntecedentesOcho(new EstadoCiudad(50,20,50,50,50,80,70),a.electoral(),a.senales(),List.of()).estadoCiudad());assertEquals("CIUDAD EN RECONSTRUCCIÓN",new AntecedentesOcho(EstadoCiudad.inicial(),a.electoral(),Map.of(),List.of()).estadoCiudad());}
 @Test void instantaneaConservaAzarProyectilesYFisica(){MotorOcho m=combate(0,false,3,1,0);m.iniciarAtaque(MotorOcho.Ataque.ORBES);m.entrada(0,MotorOcho.DER|MotorOcho.UNO|MotorOcho.SALTO);for(int i=0;i<90;i++)m.paso();MotorOcho copia=MotorOcho.restaurar(m.capturar());assertEquals(m.capturar(),copia.capturar());for(int i=0;i<180;i++){m.paso();copia.paso();}assertEquals(m.capturar(),copia.capturar());}
 @Test void pausaCongelaTodoYDescartaEntradas(){MotorOcho m=combate(0,false,1,1,0);m.entrada(0,127);m.pausar(true);Properties antes=m.capturar();for(int i=0;i<100;i++)m.paso();assertEquals(antes,m.capturar());m.pausar(false);assertEquals(0,m.entradas[0]);}
 @Test void tresFormasYCincoFasesPasanPorTransicionSegura(){MotorOcho m=combate(0,false,1,1,0);for(int fase=2;fase<=5;fase++){m.vidaJefe=(int)(m.maxVida*new double[]{0,.84,.69,.59,.39}[fase-1]);m.ataqueTicks=-10;m.paso();assertEquals(fase,m.fase);assertTrue(m.transicion>0);assertTrue(m.proyectiles.isEmpty());for(int i=0;i<100;i++)m.paso();}assertEquals(3,m.forma);assertTrue(m.plataformas().size()>10);}
 @Test void todosLosAtaquesEmitenPeligrosDespuesDelAviso(){for(var a:MotorOcho.Ataque.values()){MotorOcho m=combate(0,false,1,1,0);m.iniciarAtaque(a);for(int i=0;i<40;i++)m.paso();assertTrue(m.proyectiles.isEmpty(),a.name());for(int i=0;i<25;i++)m.paso();assertFalse(m.proyectiles.isEmpty(),a.name());}}
 @Test void saltoDobleYPlataformasSonAlcanzables(){MotorOcho m=combate(0,false,1,1,0);m.fase=5;var h=m.heroes[0];h.x=210;double minimo=h.y;for(int i=0;i<100;i++){m.entrada(0,i==0||i==25?MotorOcho.SALTO:0);m.paso();minimo=Math.min(minimo,h.y);}assertTrue(minimo<310);assertEquals(490,h.y,.01);}
 @Test void derrotaNoDaVictoriaYReintentoConservaEleccion(){MotorOcho m=combate(2,false,3,1,0);Arrays.stream(m.heroes).forEach(h->h.vida=0);m.paso();assertEquals(MotorOcho.Escena.DERROTA,m.escena);int[]v=m.votos.clone();m.reintentar();assertEquals(MotorOcho.Escena.COMBATE,m.escena);assertEquals(2,m.ganador);assertArrayEquals(v,m.votos);assertTrue(Arrays.stream(m.heroes).allMatch(h->h.vida==5));}
 @Test void victoriaPersisteUnaVezSinTocarAntecedentes()throws Exception{Path dir=ArchivosPartida.directorio();ProgresoMisiones progreso=new ProgresoMisiones(dir);for(int i=1;i<=7;i++)progreso.victoria(i);Files.writeString(dir.resolve("campana.properties"),"electoral.juan.corrupto=true\nsala.m7.anterior=1\n");String anterior=Files.readString(dir.resolve("campana.properties"));MotorOcho m=combate(2,true,1,1,0);m.fase=5;m.vidaJefe=0;m.paso();cerrarConversacion(m);assertEquals(MotorOcho.Escena.FINAL,m.escena);GuardadoOcho.acreditar(m);GuardadoOcho.acreditar(m);assertTrue(progreso.ganada(8));assertEquals(anterior,Files.readString(dir.resolve("campana.properties")));assertEquals(m.capturar(),GuardadoOcho.cargar().capturar());}
 @Test void accesoLibreNoInventaLasSieteVictorias()throws Exception{ProgresoMisiones p=new ProgresoMisiones(ArchivosPartida.directorio());p.desbloquearTodas();assertTrue(p.disponible(8));assertFalse(p.ganada(8));assertFalse(p.ganada(7));assertThrows(java.io.IOException.class,AntecedentesOcho::cargar);}
 @Test void snapshotsInvalidosSeRechazan(){var p=combate(0,false,1,1,0).capturar();p.setProperty("jefeX","NaN");assertThrows(IllegalArgumentException.class,()->MotorOcho.restaurar(p));p.setProperty("jefeX","700");p.setProperty("balas","9999999");assertThrows(IllegalArgumentException.class,()->MotorOcho.restaurar(p));}
 @Test void cuatroJugadoresEsTresContraUnoConEnfriamientos(){MotorOcho m=combate(0,false,4,1,0);assertEquals(3,m.heroes.length);m.entrada(3,1);for(int i=0;i<80;i++)m.paso();assertEquals(MotorOcho.Ataque.LLUVIA,m.ataque);int inicio=m.ataqueTicks;m.entrada(3,32);m.paso();assertTrue(m.ataqueTicks>inicio);assertEquals(MotorOcho.Ataque.LLUVIA,m.ataque);}
 @Test void elJefePermaneceVisibleEnLaArenaDePlataformas(){MotorOcho m=combate(0,false,1,1,0);m.fase=4;m.heroes[0].y=-160;m.iniciarAtaque(MotorOcho.Ataque.ORBES);assertTrue(m.jefeY>=185);assertTrue(m.jefeY<=340);}

}
